const replaceExact = (html, replacements) => {
  for (const [english, localized] of replacements) {
    if (!english || localized == null) continue;
    const escaped = english.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    html = html.replace(new RegExp(`>${escaped}<`, 'g'), `>${escape(localized)}<`)
      .replace(new RegExp(`aria-label="${escaped}"`, 'g'), `aria-label="${escape(localized)}"`)
      .replace(new RegExp(`placeholder="${escaped}"`, 'g'), `placeholder="${escape(localized)}"`)
      .replace(new RegExp(`title="${escaped}"`, 'g'), `title="${escape(localized)}"`)
      .replace(new RegExp(`data-label="${escaped}"`, 'g'), `data-label="${escape(localized)}"`);
  }
  return html;
};

const replaceTextContent = (html, replacements) => html.replace(/>([^<>]*)</g, (full, text) => {
  let localized = text;
  for (const [pattern, value] of replacements) localized = localized.replace(pattern, value);
  return `>${localized}<`;
});

