  html = html.replace(/(© 2026 Glory Star Wear\. )All rights reserved\./g, `$1${escape(t.ui.rights)}`);
  html = html.replace(/(<p>)(\d+) Colors?(<\/p>)/gi, `$1$2 ${escape(i.terms.colors)}$3`)
    .replace(/(<p>)(wide-leg pants)(<\/p>)/gi, `$1${escape(i.terms.wideLeg)}$3`)
