    // no English marketing copy leaks into the product card.
    const technicalValue = /%/.test(localizedValue) || /^\d+\s/.test(localizedValue.trim()) || /^[A-Za-z](?:[\/, -][A-Za-z0-9]+)*$/i.test(localizedValue.trim());
